with content as (
  select * from jsonb_to_recordset($content$[
    {"level":"A1","title":"The First Hello","body":"Luc is in a new English class. He knows some words, but he is afraid to speak. He thinks, \"My English is not good. People will laugh.\"\n\nThe teacher asks the students to say hello to a partner. Luc's partner is Sara. She smiles and says, \"Hello, I am Sara.\" Luc answers very quietly, \"Hello, I am Luc.\"\n\nSara does not laugh. She asks, \"How are you?\" Luc says, \"I am fine, thank you.\" These are easy words, but Luc feels proud.\n\nNext, the teacher asks them to talk about their favourite food. Luc says, \"I like rice and fish.\" His voice is a little stronger now.\n\nAt the end of the class, Luc is still a little nervous. But he has spoken English four times. He understands that courage is not the end of fear. Courage is doing a small thing while you are afraid.","summary_fr":"Luc a peur de parler dans son nouveau cours d'anglais. Grâce à des échanges simples avec Sara, il parle quatre fois et comprend que le courage peut accompagner la peur.","translation_fr":"Luc est dans un nouveau cours d'anglais. Il connaît quelques mots, mais il a peur de parler. Il pense : « Mon anglais n'est pas bon. Les gens vont rire. »\n\nLe professeur demande aux élèves de dire bonjour à un partenaire. La partenaire de Luc est Sara. Elle sourit et dit : « Bonjour, je m'appelle Sara. » Luc répond très doucement : « Bonjour, je m'appelle Luc. »\n\nSara ne rit pas. Elle demande : « Comment vas-tu ? » Luc dit : « Je vais bien, merci. » Ce sont des mots faciles, mais Luc est fier.\n\nEnsuite, le professeur leur demande de parler de leur plat préféré. Luc dit : « J'aime le riz et le poisson. » Sa voix est un peu plus forte maintenant.\n\nÀ la fin du cours, Luc est encore un peu nerveux. Mais il a parlé anglais quatre fois. Il comprend que le courage n'est pas la fin de la peur. Le courage, c'est faire une petite chose pendant qu'on a peur.","knowledge_point":"L'apprenant découvre que le courage ne supprime pas toujours la peur, mais permet de commencer par une petite action.","vocabulary":[{"word":"afraid","part_of_speech":"adjective","translation_fr":"effrayé","definition":"Feeling fear.","example":"Luc is afraid to speak."},{"word":"laugh","part_of_speech":"verb","translation_fr":"rire","definition":"To make sounds showing amusement.","example":"He thinks people will laugh."},{"word":"partner","part_of_speech":"noun","translation_fr":"partenaire","definition":"A person doing an activity with you.","example":"Sara is Luc's partner."},{"word":"quietly","part_of_speech":"adverb","translation_fr":"doucement","definition":"With very little sound.","example":"Luc answers quietly."},{"word":"proud","part_of_speech":"adjective","translation_fr":"fier","definition":"Pleased about something you did.","example":"Luc feels proud."},{"word":"voice","part_of_speech":"noun","translation_fr":"voix","definition":"The sound made when you speak.","example":"His voice is stronger."},{"word":"nervous","part_of_speech":"adjective","translation_fr":"nerveux","definition":"Worried about something that may happen.","example":"He is still a little nervous."},{"word":"courage","part_of_speech":"noun","translation_fr":"courage","definition":"The ability to act despite fear.","example":"Courage is doing a small thing."}],"questions":[{"type":"mcq","question":"Why is Luc afraid?","options":["He thinks people will laugh at his English","He has no class","He dislikes Sara","He cannot say his name"],"answer":"He thinks people will laugh at his English","explanation_fr":"Luc craint qu'on se moque de son anglais."},{"type":"mcq","question":"Who is Luc's partner?","options":["Sara","Mary","The teacher","His brother"],"answer":"Sara","explanation_fr":"Sara est sa partenaire pour l'activité."},{"type":"mcq","question":"How does Luc first answer?","options":["Very quietly","Very loudly","With a song","In writing only"],"answer":"Very quietly","explanation_fr":"Il répond d'abord très doucement."},{"type":"mcq","question":"What food does Luc like?","options":["Rice and fish","Bread and fruit","Chicken and cassava","Only vegetables"],"answer":"Rice and fish","explanation_fr":"Il dit aimer le riz et le poisson."},{"type":"mcq","question":"What happens to his voice?","options":["It becomes a little stronger","It disappears completely","It stays very angry","It becomes a song"],"answer":"It becomes a little stronger","explanation_fr":"Sa voix devient un peu plus forte."},{"type":"mcq","question":"How many times has Luc spoken English?","options":["Four times","One time","Ten times","No times"],"answer":"Four times","explanation_fr":"Le dernier paragraphe indique quatre prises de parole."},{"type":"mcq","question":"What is courage according to the text?","options":["Doing a small thing while afraid","Never feeling fear","Laughing at mistakes","Speaking perfectly"],"answer":"Doing a small thing while afraid","explanation_fr":"La conclusion définit le courage ainsi."},{"type":"true_false","question":"Sara laughs at Luc.","options":["True","False"],"answer":"False","explanation_fr":"Sara ne rit pas et continue l'échange."},{"type":"true_false","question":"Luc has no fear at the end of the class.","options":["True","False"],"answer":"False","explanation_fr":"Il reste un peu nerveux, mais il a agi."},{"type":"open","question":"What small thing can you do even if you feel afraid?","options":[],"answer":"I can say hello and answer one simple question in English with a friendly partner.","explanation_fr":"La réponse doit proposer une petite action réalisable malgré la peur."}],"grammar":[{"point":"Be afraid to","explanation_fr":"Be afraid to suivi d'une base verbale exprime la peur de faire quelque chose.","example":"He is afraid to speak."},{"point":"Past simple of say","explanation_fr":"Say devient said au prétérit, mais ici les paroles sont rapportées avec says dans le récit au présent.","example":"Luc says, 'I like rice and fish.'"}],"discussion":["When do you feel nervous in English?","What small sentence can you say first?","How can a partner help you?"]},
    {"level":"A2","title":"A Small Presentation","body":"Mireille has to give a short presentation about her studies. She knows her subject well, but she is afraid of speaking in front of the class. Two days before the presentation, she cannot sleep well and thinks about everything that could go wrong.\n\nHer friend suggests practising in small steps. First, Mireille reads her notes aloud alone. Then she presents to her friend for two minutes. Her friend listens and asks one simple question. Mireille answers it without reading every word.\n\nNext, they practise with two more students. Mireille feels nervous again, but she uses three cards with key words instead of a full text. The cards help her look at the audience more often.\n\nOn the day of the presentation, her hands shake a little. She takes a breath, looks at her first card and begins. She forgets one example, but she continues and answers a question at the end.\n\nThe presentation is not perfect, and Mireille does not expect it to be. She has completed the task she feared. Her teacher gives her advice for next time, and she writes it down.\n\nMireille learns that preparation does not remove every uncomfortable feeling. It gives her something familiar to do when fear appears. Each practice step made the real situation a little less unknown.","summary_fr":"Mireille prépare une présentation en plusieurs étapes, seule puis devant quelques personnes. Le jour venu, elle reste nerveuse mais termine son exposé et utilise les conseils reçus.","translation_fr":"Mireille doit faire une courte présentation sur ses études. Elle connaît bien son sujet, mais elle a peur de parler devant la classe. Deux jours avant la présentation, elle dort mal et pense à tout ce qui pourrait mal se passer.\n\nSon amie suggère de s'entraîner par petites étapes. D'abord, Mireille lit ses notes à voix haute seule. Ensuite, elle fait une présentation de deux minutes devant son amie. Son amie écoute et pose une question simple. Mireille répond sans lire chaque mot.\n\nPuis, elles s'entraînent avec deux autres étudiants. Mireille se sent de nouveau nerveuse, mais elle utilise trois cartes avec des mots-clés au lieu d'un texte complet. Les cartes l'aident à regarder le public plus souvent.\n\nLe jour de la présentation, ses mains tremblent un peu. Elle prend une inspiration, regarde sa première carte et commence. Elle oublie un exemple, mais elle continue et répond à une question à la fin.\n\nLa présentation n'est pas parfaite et Mireille ne s'attend pas à ce qu'elle le soit. Elle a terminé la tâche qu'elle craignait. Son professeur lui donne un conseil pour la prochaine fois et elle le note.\n\nMireille apprend que la préparation ne supprime pas tous les sentiments désagréables. Elle lui donne quelque chose de familier à faire lorsque la peur apparaît. Chaque étape d'entraînement a rendu la situation réelle un peu moins inconnue.","knowledge_point":"L'apprenant découvre la préparation progressive, les repères simples et l'acceptation de l'imperfection pour affronter une prise de parole.","vocabulary":[{"word":"presentation","part_of_speech":"noun","translation_fr":"présentation, exposé","definition":"A talk giving information to an audience.","example":"She gives a short presentation."},{"word":"go wrong","part_of_speech":"verb phrase","translation_fr":"mal se passer","definition":"To fail or develop problems.","example":"She thinks about what could go wrong."},{"word":"aloud","part_of_speech":"adverb","translation_fr":"à voix haute","definition":"In a voice that can be heard.","example":"She reads her notes aloud."},{"word":"key words","part_of_speech":"noun phrase","translation_fr":"mots-clés","definition":"Important words that remind you of ideas.","example":"Her cards contain key words."},{"word":"audience","part_of_speech":"noun","translation_fr":"public","definition":"The people watching or listening.","example":"She looks at the audience."},{"word":"shake","part_of_speech":"verb","translation_fr":"trembler","definition":"To move quickly from side to side.","example":"Her hands shake a little."},{"word":"uncomfortable","part_of_speech":"adjective","translation_fr":"désagréable","definition":"Causing physical or emotional discomfort.","example":"Preparation does not remove every uncomfortable feeling."},{"word":"unknown","part_of_speech":"adjective","translation_fr":"inconnu","definition":"Not familiar or not known.","example":"Practice makes the situation less unknown."}],"questions":[{"type":"mcq","question":"What is Mireille's presentation about?","options":["Her studies","Her favourite food","A new business","A football match"],"answer":"Her studies","explanation_fr":"Elle présente ses études."},{"type":"mcq","question":"What happens two days before?","options":["She cannot sleep well","She gives the presentation","She stops preparing","She loses every note"],"answer":"She cannot sleep well","explanation_fr":"L'inquiétude perturbe son sommeil deux jours avant."},{"type":"mcq","question":"What is her first practice step?","options":["Reading notes aloud alone","Presenting to the whole class","Answering difficult questions","Speaking without preparation"],"answer":"Reading notes aloud alone","explanation_fr":"Elle commence seule avec ses notes."},{"type":"mcq","question":"What does her friend do?","options":["Listens and asks one simple question","Reads the whole presentation","Laughs at her mistakes","Gives her a full text"],"answer":"Listens and asks one simple question","explanation_fr":"L'amie écoute puis pose une question simple."},{"type":"mcq","question":"What is on Mireille's three cards?","options":["Key words","Every sentence","Only pictures","The teacher's advice"],"answer":"Key words","explanation_fr":"Les cartes contiennent des mots-clés."},{"type":"mcq","question":"What happens during the real presentation?","options":["She forgets one example but continues","She leaves immediately","She reads every word","Nobody listens"],"answer":"She forgets one example but continues","explanation_fr":"Elle oublie un exemple sans interrompre sa présentation."},{"type":"mcq","question":"What does she do with the teacher's advice?","options":["Writes it down","Ignores it","Reads it to the audience","Throws it away"],"answer":"Writes it down","explanation_fr":"Elle note le conseil pour la prochaine fois."},{"type":"true_false","question":"Mireille expects a perfect presentation.","options":["True","False"],"answer":"False","explanation_fr":"Elle accepte que la présentation ne soit pas parfaite."},{"type":"true_false","question":"Practice makes the situation more familiar.","options":["True","False"],"answer":"True","explanation_fr":"Chaque étape réduit le caractère inconnu de la situation."},{"type":"open","question":"How could you prepare for a short presentation in small steps?","options":[],"answer":"I can practise alone, then with one friend, use key-word cards and ask for one piece of advice after speaking.","explanation_fr":"La réponse doit proposer une progression et un moyen concret de préparation."}],"grammar":[{"point":"Be afraid of plus ing","explanation_fr":"Après be afraid of, le verbe prend la forme en ing.","example":"She is afraid of speaking in front of the class."},{"point":"Instead of for alternatives","explanation_fr":"Instead of suivi d'un nom ou d'un gérondif présente un choix à la place d'un autre.","example":"She uses key words instead of a full text."}],"discussion":["What situation makes you nervous?","Which practice step would make it more familiar?","Why is an imperfect presentation still valuable?"]},
    {"level":"B1","title":"Courage Is a Practice","body":"When people say they want to be more confident, they often imagine a future version of themselves who feels no fear. This picture can be discouraging because it makes confidence seem like a personality trait that other people naturally possess.\n\nA more practical view is to see courage as a practice. You choose an action that is challenging but manageable, prepare for it and observe what happens. The aim is not to prove that you are fearless. It is to discover that you can act, learn and recover even when the situation feels uncomfortable.\n\nFor example, if speaking in a group makes you nervous, you do not need to begin with a long speech. You could prepare one question and ask it during a small meeting. Before the meeting, write the question and practise saying it aloud. Afterwards, note what actually happened rather than what you feared would happen.\n\nThis record matters because fear often gives more attention to possible embarrassment than to real evidence. Perhaps nobody laughed. Perhaps one person answered helpfully. Perhaps your voice shook, but the group still understood you. These details provide a more balanced memory.\n\nPreparation should not become another way to avoid action. If you spend weeks rewriting one question but never ask it, preparation has stopped serving its purpose. Choose a simple level of readiness, then act.\n\nOver time, repeated experiences can change your expectations. You learn that a mistake is usually an event to handle, not a definition of who you are. Confidence grows less from telling yourself that nothing can go wrong and more from knowing that you can respond when something does.","summary_fr":"Le courage se développe par des défis progressifs, une préparation limitée et l'observation des faits. La confiance vient moins de l'absence de problèmes que de la capacité à y répondre.","translation_fr":"Quand les gens disent vouloir être plus confiants, ils imaginent souvent une future version d'eux-mêmes qui ne ressent aucune peur. Cette image peut décourager parce qu'elle fait de la confiance un trait de personnalité que d'autres possèdent naturellement.\n\nUne vision plus pratique consiste à voir le courage comme un entraînement. Vous choisissez une action difficile mais gérable, vous la préparez et vous observez ce qui arrive. Le but n'est pas de prouver que vous n'avez peur de rien. Il est de découvrir que vous pouvez agir, apprendre et vous rétablir même lorsque la situation est désagréable.\n\nPar exemple, si parler dans un groupe vous rend nerveux, vous n'avez pas besoin de commencer par un long discours. Vous pourriez préparer une question et la poser pendant une petite réunion. Avant la réunion, écrivez la question et entraînez-vous à la dire à voix haute. Ensuite, notez ce qui s'est réellement passé plutôt que ce que vous craigniez.\n\nCette trace compte parce que la peur accorde souvent plus d'attention à l'embarras possible qu'aux preuves réelles. Peut-être que personne n'a ri. Peut-être qu'une personne a répondu avec bienveillance. Peut-être que votre voix a tremblé, mais que le groupe vous a quand même compris. Ces détails créent un souvenir plus équilibré.\n\nLa préparation ne doit pas devenir une autre façon d'éviter l'action. Si vous passez des semaines à réécrire une question sans jamais la poser, la préparation ne remplit plus son rôle. Choisissez un niveau simple de préparation, puis agissez.\n\nAvec le temps, les expériences répétées peuvent changer vos attentes. Vous apprenez qu'une erreur est généralement un événement à gérer, pas une définition de votre identité. La confiance vient moins du fait de se dire que rien ne peut mal se passer que de savoir qu'on peut réagir quand quelque chose arrive.","knowledge_point":"L'apprenant comprend le rôle des défis progressifs, des preuves réelles et de l'action dans le développement de la confiance.","vocabulary":[{"word":"confident","part_of_speech":"adjective","translation_fr":"confiant","definition":"Feeling able to do something successfully.","example":"She wants to be more confident."},{"word":"trait","part_of_speech":"noun","translation_fr":"trait","definition":"A characteristic of a person.","example":"Confidence is not simply a natural trait."},{"word":"manageable","part_of_speech":"adjective","translation_fr":"gérable","definition":"Possible to deal with.","example":"Choose a challenging but manageable action."},{"word":"recover","part_of_speech":"verb","translation_fr":"se rétablir, se reprendre","definition":"To return to a normal state after difficulty.","example":"You can recover after an uncomfortable moment."},{"word":"embarrassment","part_of_speech":"noun","translation_fr":"embarras","definition":"A feeling of shame or discomfort.","example":"Fear focuses on possible embarrassment."},{"word":"balanced","part_of_speech":"adjective","translation_fr":"équilibré","definition":"Considering different sides fairly.","example":"The details create a balanced memory."},{"word":"readiness","part_of_speech":"noun","translation_fr":"état de préparation","definition":"The state of being ready to act.","example":"Choose a simple level of readiness."},{"word":"expectation","part_of_speech":"noun","translation_fr":"attente","definition":"A belief about what will happen.","example":"Experience can change your expectations."}],"questions":[{"type":"mcq","question":"What picture of confidence can discourage people?","options":["A future self who feels no fear","A person who practises gradually","Someone who records evidence","A person asking one question"],"answer":"A future self who feels no fear","explanation_fr":"L'image d'une absence totale de peur peut paraître inaccessible."},{"type":"mcq","question":"How does the text define courage as a practice?","options":["Choose a manageable challenge, prepare and observe","Wait until all fear disappears","Begin with the hardest speech possible","Avoid every uncomfortable situation"],"answer":"Choose a manageable challenge, prepare and observe","explanation_fr":"Ces trois étapes résument la pratique proposée."},{"type":"mcq","question":"What could a nervous speaker do in a small meeting?","options":["Ask one prepared question","Give a long speech","Remain silent for weeks","Rewrite notes without acting"],"answer":"Ask one prepared question","explanation_fr":"Une question préparée est un premier défi gérable."},{"type":"mcq","question":"What should the speaker record afterwards?","options":["What actually happened","Only what was feared","Other people's private thoughts","A definition of personal identity"],"answer":"What actually happened","explanation_fr":"Le bilan doit porter sur les faits réels."},{"type":"mcq","question":"Why is a balanced memory useful?","options":["Fear may focus too much on embarrassment","It proves nothing can go wrong","It removes the need for preparation","It hides every mistake"],"answer":"Fear may focus too much on embarrassment","explanation_fr":"Les faits contrent l'attention excessive donnée à l'embarras."},{"type":"mcq","question":"When does preparation become avoidance?","options":["When weeks of rewriting replace action","When you practise one question aloud","When you choose a manageable step","When you review evidence"],"answer":"When weeks of rewriting replace action","explanation_fr":"Préparer sans jamais agir ne remplit plus le but."},{"type":"mcq","question":"What is a mistake according to the conclusion?","options":["An event to handle","A definition of identity","Proof that confidence is impossible","A reason to stop learning"],"answer":"An event to handle","explanation_fr":"Le texte sépare l'erreur de l'identité personnelle."},{"type":"true_false","question":"The aim is to prove that you are fearless.","options":["True","False"],"answer":"False","explanation_fr":"Le but est d'agir et d'apprendre malgré l'inconfort."},{"type":"true_false","question":"Confidence can grow from knowing you can respond to problems.","options":["True","False"],"answer":"True","explanation_fr":"C'est l'idée exprimée dans la dernière phrase."},{"type":"open","question":"Choose one manageable courageous action and say what evidence you will record.","options":[],"answer":"I will ask one prepared question in a small meeting, then record whether people understood and how they responded.","explanation_fr":"La réponse doit définir un défi gérable et des faits à observer."}],"grammar":[{"point":"Comparative with less and more","explanation_fr":"Less et more comparent l'importance ou la quantité entre deux idées.","example":"Confidence grows less from telling yourself and more from knowing."},{"point":"What clauses","explanation_fr":"What peut introduire une proposition qui décrit une chose ou un événement.","example":"Note what actually happened."}],"discussion":["Which manageable challenge could build your confidence?","How can preparation turn into avoidance?","What evidence helps you remember an experience fairly?"]},
    {"level":"B2","title":"Working with Fear Instead of Waiting","body":"Fear is often interpreted as a signal to postpone action. We tell ourselves that we will apply, speak or begin when we feel ready. Sometimes waiting is sensible, particularly when information or preparation is genuinely missing. At other times, readiness becomes a moving target: each rehearsal reveals another detail that could be improved, while the feared action remains untested.\n\nA useful distinction is between danger and discomfort. Danger requires protection and may justify avoiding a situation. Discomfort, although unpleasant, can sometimes accompany a worthwhile challenge. Asking a question in a supportive class may produce embarrassment, but it is not the same as entering an unsafe environment. Treating both identically can unnecessarily reduce your choices.\n\nOnce a challenge is reasonably safe and meaningful, divide it into a version you can attempt. If contributing to a large meeting feels overwhelming, you might first share a view in a smaller group. The aim is not to make the experience effortless. It is to create an opportunity to learn that you can tolerate some uncertainty and still act effectively.\n\nDuring the experience, attention may turn inward. You monitor your voice, hands and every possible mistake, leaving less attention for the task itself. A simple external focus can help: listen to the question being asked, look at the person you are helping or concentrate on the message you want to communicate.\n\nAfterwards, evaluate the action by more than emotional comfort. Feeling nervous does not automatically mean that you performed badly. Ask whether you completed the important part, what you learned and what would make the next attempt more effective.\n\nOvercoming fear is therefore not a single victory after which anxiety never returns. It is a process of choosing meaningful action, distinguishing risk from unease and building evidence that discomfort does not have to make your decisions for you.","summary_fr":"Il faut distinguer danger et inconfort, préparer un défi progressif et recentrer son attention sur la tâche. L'évaluation porte sur l'action et l'apprentissage, pas seulement sur l'émotion ressentie.","translation_fr":"La peur est souvent interprétée comme un signal invitant à reporter l'action. Nous nous disons que nous postulerons, parlerons ou commencerons quand nous nous sentirons prêts. Parfois, attendre est raisonnable, surtout lorsqu'il manque réellement des informations ou de la préparation. À d'autres moments, la préparation devient une cible mouvante : chaque répétition révèle un détail à améliorer, tandis que l'action redoutée reste inexpérimentée.\n\nUne distinction utile sépare le danger de l'inconfort. Le danger exige une protection et peut justifier d'éviter une situation. L'inconfort, bien que désagréable, peut parfois accompagner un défi valable. Poser une question dans une classe bienveillante peut produire de l'embarras, mais ce n'est pas comme entrer dans un environnement dangereux. Traiter les deux de la même façon peut réduire inutilement vos choix.\n\nLorsqu'un défi est raisonnablement sûr et significatif, divisez-le en une version que vous pouvez tenter. Si contribuer à une grande réunion semble écrasant, vous pourriez d'abord partager une opinion dans un petit groupe. Le but n'est pas de rendre l'expérience sans effort. Il est de créer une occasion d'apprendre que vous pouvez tolérer une certaine incertitude et agir efficacement.\n\nPendant l'expérience, l'attention peut se tourner vers l'intérieur. Vous surveillez votre voix, vos mains et chaque erreur possible, ce qui laisse moins d'attention à la tâche. Un simple focus extérieur peut aider : écoutez la question posée, regardez la personne que vous aidez ou concentrez-vous sur le message à communiquer.\n\nEnsuite, évaluez l'action sur autre chose que le confort émotionnel. Se sentir nerveux ne signifie pas automatiquement avoir mal réussi. Demandez-vous si vous avez terminé la partie importante, ce que vous avez appris et ce qui rendrait la prochaine tentative plus efficace.\n\nSurmonter la peur n'est donc pas une victoire unique après laquelle l'anxiété ne revient jamais. C'est un processus qui consiste à choisir une action significative, distinguer le risque du malaise et accumuler des preuves que l'inconfort ne doit pas prendre vos décisions à votre place.","knowledge_point":"L'apprenant distingue sécurité et inconfort, utilise une progression réaliste et évalue une action selon des critères plus larges que l'émotion.","vocabulary":[{"word":"postpone","part_of_speech":"verb","translation_fr":"reporter","definition":"To delay an action until later.","example":"Fear can make us postpone action."},{"word":"moving target","part_of_speech":"noun phrase","translation_fr":"cible mouvante","definition":"A goal that keeps changing and is difficult to reach.","example":"Readiness can become a moving target."},{"word":"discomfort","part_of_speech":"noun","translation_fr":"inconfort","definition":"An unpleasant physical or emotional feeling.","example":"Discomfort can accompany a challenge."},{"word":"worthwhile","part_of_speech":"adjective","translation_fr":"valable, utile","definition":"Worth the time or effort required.","example":"Choose a worthwhile challenge."},{"word":"overwhelming","part_of_speech":"adjective","translation_fr":"écrasant","definition":"So intense that it feels difficult to manage.","example":"A large meeting may feel overwhelming."},{"word":"tolerate","part_of_speech":"verb","translation_fr":"tolérer","definition":"To accept and deal with something unpleasant.","example":"You can tolerate some uncertainty."},{"word":"inward","part_of_speech":"adverb","translation_fr":"vers l'intérieur","definition":"Towards your own thoughts or feelings.","example":"Attention may turn inward."},{"word":"unease","part_of_speech":"noun","translation_fr":"malaise","definition":"A feeling of worry or discomfort.","example":"Distinguish risk from unease."}],"questions":[{"type":"mcq","question":"When can waiting be sensible?","options":["When information or preparation is genuinely missing","Whenever a task is meaningful","Only after every fear disappears","When no improvement is possible"],"answer":"When information or preparation is genuinely missing","explanation_fr":"Le texte reconnaît qu'une préparation réelle peut justifier d'attendre."},{"type":"mcq","question":"What happens when readiness becomes a moving target?","options":["The feared action remains untested","Every rehearsal becomes unnecessary","Danger disappears","Choices always increase"],"answer":"The feared action remains untested","explanation_fr":"Les détails à améliorer remplacent continuellement le passage à l'action."},{"type":"mcq","question":"Why distinguish danger from discomfort?","options":["They do not require the same response","Both always require avoidance","Discomfort is never unpleasant","Danger is only emotional"],"answer":"They do not require the same response","explanation_fr":"Le danger exige une protection, tandis qu'un inconfort peut accompagner un défi."},{"type":"mcq","question":"What is a suitable first step for a large meeting?","options":["Share a view in a smaller group","Wait for perfect confidence","Avoid every group","Memorise every possible answer"],"answer":"Share a view in a smaller group","explanation_fr":"Un petit groupe offre une version plus accessible du défi."},{"type":"mcq","question":"What can excessive inward attention reduce?","options":["Attention available for the task","The meaning of the challenge","The need for evaluation","All physical feelings permanently"],"answer":"Attention available for the task","explanation_fr":"Surveiller chaque réaction laisse moins d'attention au message."},{"type":"mcq","question":"Which is an external focus?","options":["Listening to the question being asked","Monitoring your hands","Imagining every mistake","Judging your voice repeatedly"],"answer":"Listening to the question being asked","explanation_fr":"Écouter la question tourne l'attention vers la tâche."},{"type":"mcq","question":"How should an attempt be evaluated?","options":["By completion, learning and possible improvement","Only by emotional comfort","Only by the absence of nerves","By whether no mistake occurred"],"answer":"By completion, learning and possible improvement","explanation_fr":"Ces critères donnent une évaluation plus complète."},{"type":"true_false","question":"Feeling nervous automatically proves poor performance.","options":["True","False"],"answer":"False","explanation_fr":"L'émotion ne suffit pas à évaluer la performance."},{"type":"true_false","question":"Overcoming fear means anxiety can never return.","options":["True","False"],"answer":"False","explanation_fr":"Le texte présente un processus plutôt qu'une victoire définitive."},{"type":"open","question":"Describe a meaningful challenge and a smaller version you could attempt.","options":[],"answer":"I could first present one idea to three colleagues before presenting to a large meeting, then review what I communicated and learned.","explanation_fr":"La réponse doit proposer une progression sûre, significative et évaluable."}],"grammar":[{"point":"Participle clauses","explanation_fr":"Une proposition participiale peut relier une observation à sa conséquence.","example":"Treating both identically can unnecessarily reduce your choices."},{"point":"Not the same as","explanation_fr":"Cette structure compare deux situations et marque leur différence.","example":"It is not the same as entering an unsafe environment."}],"discussion":["How do you distinguish a risky situation from an uncomfortable one?","What external focus helps you during a challenge?","Which criteria show that an attempt was useful?"]},
    {"level":"C1","title":"Fear, Avoidance and Deliberate Exposure","body":"Avoidance is attractive because it often works immediately. Cancel the presentation, leave the conversation or postpone the application, and the uncomfortable sensation may subside. That relief can teach a misleading lesson: that escape was necessary and the original situation was beyond your capacity. The cost appears later, when the range of activities you are willing to attempt becomes narrower.\n\nDeliberate exposure offers a different principle. A person approaches a chosen, reasonably safe challenge in a measured way, rather than waiting for fear to disappear. This is not an instruction to ignore danger or force yourself into overwhelming situations. It means distinguishing a meaningful discomfort from a threat that requires protection, and selecting a step that can be attempted with appropriate support.\n\nThe purpose of the step is not to produce a flawless performance. It is to gather better evidence. Beforehand, fear may predict humiliation, incompetence or permanent rejection. Afterwards, a careful review can examine what occurred: perhaps the audience remained attentive, perhaps a mistake required correction, perhaps the experience was indeed more difficult than expected. Even the last outcome can inform preparation without proving personal inadequacy.\n\nThere is, however, a difference between exposure and mere endurance. If someone repeatedly enters situations without reflection, support or a way to adjust the difficulty, the exercise may simply reinforce exhaustion. A deliberate approach includes a reason, a manageable scale and a debrief. It also respects the possibility of stopping when circumstances become unsafe.\n\nSelf-criticism can undermine this process by turning each attempt into a trial of personal worth. A more useful stance is curiosity: what did I anticipate, what did I notice, and what skill would change the next attempt? Curiosity does not deny discomfort. It prevents discomfort from becoming the only available information.\n\nOver time, courage may look less like dramatic fearlessness and more like flexibility. The person can acknowledge fear, assess the situation, choose a proportionate response and remain connected to a valued direction. Freedom consists not in never feeling afraid, but in expanding the range of actions that fear no longer has the sole authority to decide.","summary_fr":"L'évitement soulage immédiatement mais réduit les possibilités. Une exposition délibérée, sûre et progressive permet de recueillir des preuves, avec curiosité, soutien et bilan, sans confondre courage et endurance forcée.","translation_fr":"L'évitement est séduisant parce qu'il fonctionne souvent immédiatement. Annulez la présentation, quittez la conversation ou reportez la candidature, et la sensation désagréable peut diminuer. Ce soulagement peut enseigner une leçon trompeuse : que la fuite était nécessaire et que la situation initiale dépassait vos capacités. Le coût apparaît plus tard, lorsque l'ensemble des activités que vous acceptez de tenter se rétrécit.\n\nL'exposition délibérée propose un autre principe. Une personne aborde un défi choisi et raisonnablement sûr de manière mesurée, au lieu d'attendre que la peur disparaisse. Il ne s'agit pas d'ignorer un danger ni de se forcer à affronter des situations écrasantes. Il s'agit de distinguer un inconfort significatif d'une menace qui exige une protection, puis de choisir une étape réalisable avec un soutien approprié.\n\nLe but de cette étape n'est pas de produire une performance parfaite. Il est de recueillir de meilleures preuves. Avant, la peur peut prédire l'humiliation, l'incompétence ou un rejet définitif. Après, un bilan attentif peut examiner ce qui s'est produit : peut-être que le public est resté attentif, peut-être qu'une erreur a demandé une correction, peut-être que l'expérience était effectivement plus difficile que prévu. Même ce dernier résultat peut éclairer la préparation sans prouver une incapacité personnelle.\n\nIl existe cependant une différence entre exposition et simple endurance. Si quelqu'un entre répétitivement dans des situations sans réflexion, soutien ou moyen d'ajuster la difficulté, l'exercice peut simplement renforcer l'épuisement. Une approche délibérée comprend une raison, une échelle gérable et un bilan. Elle respecte aussi la possibilité d'arrêter lorsque les circonstances deviennent dangereuses.\n\nL'autocritique peut fragiliser ce processus en transformant chaque tentative en procès de la valeur personnelle. Une attitude plus utile est la curiosité : qu'avais-je anticipé, qu'ai-je remarqué et quelle compétence changerait la prochaine tentative ? La curiosité ne nie pas l'inconfort. Elle empêche l'inconfort de devenir la seule information disponible.\n\nAvec le temps, le courage peut ressembler moins à une absence spectaculaire de peur et davantage à de la flexibilité. La personne peut reconnaître la peur, évaluer la situation, choisir une réponse proportionnée et rester liée à une direction valorisée. La liberté ne consiste pas à ne jamais avoir peur, mais à élargir l'ensemble des actions que la peur n'a plus l'autorité unique de décider.","knowledge_point":"L'apprenant analyse l'évitement, l'exposition progressive et le bilan factuel, tout en préservant la sécurité et la valeur personnelle.","vocabulary":[{"word":"subside","part_of_speech":"verb","translation_fr":"s'apaiser","definition":"To become less intense.","example":"The uncomfortable sensation may subside."},{"word":"misleading","part_of_speech":"adjective","translation_fr":"trompeur","definition":"Giving a false or inaccurate idea.","example":"Relief can teach a misleading lesson."},{"word":"exposure","part_of_speech":"noun","translation_fr":"exposition","definition":"Deliberately approaching a situation that causes discomfort.","example":"Deliberate exposure uses a measured challenge."},{"word":"humiliation","part_of_speech":"noun","translation_fr":"humiliation","definition":"A strong feeling of being made to appear foolish or worthless.","example":"Fear may predict humiliation."},{"word":"inadequacy","part_of_speech":"noun","translation_fr":"insuffisance","definition":"The state of not being good enough.","example":"Difficulty does not prove personal inadequacy."},{"word":"endurance","part_of_speech":"noun","translation_fr":"endurance","definition":"The ability to keep suffering through something difficult.","example":"Exposure is not mere endurance."},{"word":"undermine","part_of_speech":"verb","translation_fr":"fragiliser","definition":"To gradually weaken something.","example":"Self-criticism can undermine the process."},{"word":"proportionate","part_of_speech":"adjective","translation_fr":"proportionné","definition":"Appropriate in size or degree to the situation.","example":"Choose a proportionate response."}],"questions":[{"type":"mcq","question":"Why is avoidance immediately attractive?","options":["It can reduce discomfort quickly","It always expands future choices","It provides complete evidence","It guarantees better preparation"],"answer":"It can reduce discomfort quickly","explanation_fr":"L'évitement produit souvent un soulagement immédiat."},{"type":"mcq","question":"What misleading lesson can relief teach?","options":["That escape was necessary and the situation exceeded capacity","That fear never returns","That every challenge is dangerous","That preparation is unnecessary"],"answer":"That escape was necessary and the situation exceeded capacity","explanation_fr":"Le soulagement peut renforcer une croyance erronée sur ses capacités."},{"type":"mcq","question":"What does deliberate exposure require?","options":["A chosen, reasonably safe and measured challenge","Ignoring every threat","A flawless performance","Entering overwhelming situations without support"],"answer":"A chosen, reasonably safe and measured challenge","explanation_fr":"L'exposition délibérée respecte sécurité, choix et progression."},{"type":"mcq","question":"What is the main purpose of the attempted step?","options":["To gather better evidence","To prove personal worth","To eliminate all discomfort","To avoid feedback"],"answer":"To gather better evidence","explanation_fr":"L'essai sert à comparer les prédictions avec les faits."},{"type":"mcq","question":"How can a harder-than-expected experience still help?","options":["It can inform future preparation","It proves inadequacy","It makes support useless","It requires permanent avoidance"],"answer":"It can inform future preparation","explanation_fr":"Même une difficulté réelle fournit des informations utiles."},{"type":"mcq","question":"What distinguishes exposure from mere endurance?","options":["Reason, manageable scale, support and debrief","Repeated exhaustion without adjustment","A complete absence of choice","Ignoring unsafe circumstances"],"answer":"Reason, manageable scale, support and debrief","explanation_fr":"Ces éléments rendent la démarche réfléchie et ajustable."},{"type":"mcq","question":"Which questions express a curious stance?","options":["What did I anticipate, notice and need to learn?","What is wrong with me?","Why must I always fail?","How can I avoid every attempt?"],"answer":"What did I anticipate, notice and need to learn?","explanation_fr":"La curiosité examine prédictions, observations et compétences."},{"type":"true_false","question":"The text recommends continuing even when circumstances become unsafe.","options":["True","False"],"answer":"False","explanation_fr":"Il faut pouvoir arrêter si la situation devient dangereuse."},{"type":"true_false","question":"Courage can involve flexibility rather than dramatic fearlessness.","options":["True","False"],"answer":"True","explanation_fr":"La conclusion redéfinit le courage comme une flexibilité face à la peur."},{"type":"open","question":"Design a deliberate exposure step with a safety condition and a debrief question.","options":[],"answer":"I will share one idea in a supportive small group, stop if the situation becomes hostile or unsafe, and afterwards ask what actually happened and what skill I should practise next.","explanation_fr":"La réponse doit inclure un défi mesuré, une limite de sécurité et une question de bilan."}],"grammar":[{"point":"Rather than for contrast","explanation_fr":"Rather than oppose la méthode choisie à une attente ou à une autre conduite.","example":"Approach a measured challenge rather than waiting for fear to disappear."},{"point":"Not in but in for definition","explanation_fr":"Cette structure corrige une définition avant de présenter celle qui est retenue.","example":"Freedom consists not in never feeling afraid, but in expanding the range of actions."}],"discussion":["When has avoidance reduced your choices?","What makes an exposure step deliberate rather than forced?","How can curiosity change your review of a difficult attempt?"]}
  ]$content$::jsonb) as x(
    level public.rw_level,title text,body text,summary_fr text,translation_fr text,
    knowledge_point text,vocabulary jsonb,questions jsonb,grammar jsonb,discussion jsonb
  )
)
insert into public.rw_lessons(session_id,level,title,body,word_count,summary_fr,translation_fr,knowledge_point,vocabulary,questions,grammar,discussion,mention,status,content_type,rights_status,published_at)
select s.id,c.level,c.title,c.body,cardinality(regexp_split_to_array(btrim(c.body),'[[:space:]]+')),
 c.summary_fr,c.translation_fr,c.knowledge_point,c.vocabulary,c.questions,c.grammar,c.discussion,
 'original','published','original text','Texte original OpenDoorsClass',now()
from content c join public.rw_weeks w on w.week_number=4 join public.rw_sessions s on s.week_id=w.id and s.day_index=3
on conflict(session_id,level) do update set title=excluded.title,body=excluded.body,word_count=excluded.word_count,
 summary_fr=excluded.summary_fr,translation_fr=excluded.translation_fr,knowledge_point=excluded.knowledge_point,
 vocabulary=excluded.vocabulary,questions=excluded.questions,grammar=excluded.grammar,discussion=excluded.discussion,
 mention='original',status='published',content_type='original text',rights_status='Texte original OpenDoorsClass',
 published_at=coalesce(rw_lessons.published_at,now()) where rw_lessons.status<>'published';
do $$ declare invalid_count integer; begin
 select count(*) into invalid_count from public.rw_lessons l join public.rw_sessions s on s.id=l.session_id
 join public.rw_weeks w on w.id=s.week_id where w.week_number=4 and s.day_index=3 and
 (l.status<>'published' or jsonb_array_length(l.questions)<>10 or jsonb_array_length(l.vocabulary)<8
 or jsonb_array_length(l.grammar)<>2 or jsonb_array_length(l.discussion)<>3 or l.body='' or coalesce(l.translation_fr,'')='');
 if invalid_count<>0 then raise exception 'Validation impossible: % leçons incomplètes',invalid_count; end if;
end $$;